(() => {
  const body = document.body;
  const hamburger = document.querySelector(".hamburger");
  const navLinksContainer = document.getElementById("nav-links");
  const pageLinks = document.querySelectorAll('a[href^="#"]');
  const backToTopButton = document.querySelector(".back-to-top");
  const animatedElements = document.querySelectorAll("[data-animate]");
  const navLinks = document.querySelectorAll(".nav-links a");

  const setNavigationState = (isOpen) => {
    navLinksContainer?.classList.toggle("open", isOpen);
    body.classList.toggle("nav-open", isOpen);
    hamburger?.setAttribute("aria-expanded", String(isOpen));
  };

  hamburger?.addEventListener("click", () => {
    const isOpen = navLinksContainer?.classList.contains("open");
    setNavigationState(!isOpen);
  });

  pageLinks.forEach((link) => {
    link.addEventListener("click", (event) => {
      const targetSelector = link.getAttribute("href");
      if (!targetSelector || targetSelector === "#") {
        return;
      }

      const targetElement = document.querySelector(targetSelector);
      if (!targetElement) {
        return;
      }

      event.preventDefault();
      targetElement.scrollIntoView({ behavior: "smooth" });

      if (event.currentTarget.closest(".nav-links")) {
        setNavigationState(false);
      }
    });
  });

  const updateBackToTopButton = () => {
    backToTopButton?.classList.toggle("show", window.scrollY > 260);
  };

  window.addEventListener("scroll", updateBackToTopButton);
  backToTopButton?.addEventListener("click", () => {
    window.scrollTo({ top: 0, behavior: "smooth" });
  });

  const animationObserver = new IntersectionObserver(
    (entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          entry.target.classList.add("in-view");
        }
      });
    },
    { threshold: 0.12 }
  );

  animatedElements.forEach((element) => animationObserver.observe(element));

  const counterObserver = new IntersectionObserver(
    (entries, observer) => {
      entries.forEach((entry) => {
        if (!entry.isIntersecting) {
          return;
        }

        const counter = entry.target;
        const targetValue = Number.parseInt(counter.getAttribute("data-counter"), 10) || 0;
        const duration = Math.max(600, targetValue * 15);
        const startTime = performance.now();

        const animateCounter = (timestamp) => {
          const elapsed = timestamp - startTime;
          const progress = Math.min(elapsed / duration, 1);
          counter.textContent = String(Math.round(targetValue * progress));

          if (progress < 1) {
            requestAnimationFrame(animateCounter);
          } else {
            counter.textContent = String(targetValue);
          }
        };

        requestAnimationFrame(animateCounter);
        observer.unobserve(counter);
      });
    },
    { threshold: 0.4 }
  );

  document.querySelectorAll("[data-counter]").forEach((counter) => counterObserver.observe(counter));

  const updateActiveNavLink = () => {
    const scrollMarker = window.scrollY + 90;

    navLinks.forEach((link) => {
      const targetSelector = link.getAttribute("href");
      if (!targetSelector) {
        return;
      }

      const section = document.querySelector(targetSelector);
      if (!section) {
        return;
      }

      const sectionTop = section.offsetTop;
      const sectionBottom = sectionTop + section.offsetHeight;
      const isActive = scrollMarker >= sectionTop && scrollMarker < sectionBottom;
      link.classList.toggle("active", isActive);
    });
  };

  window.addEventListener("scroll", updateActiveNavLink);

  const form = document.getElementById("contact-form");
  const status = document.getElementById("form-status");
  const submitButton = document.getElementById("submit-btn");

  const setFormStatus = (message, type) => {
    if (!status) {
      return;
    }

    status.textContent = message;
    status.style.color = type === "success" ? "#0b8a42" : "#b00020";
  };

  const toggleFieldError = (fieldName, isValid) => {
    const input = form?.elements?.[fieldName];
    const error = document.getElementById(`error-${fieldName}`);
    if (!input || !error) {
      return;
    }

    input.setAttribute("aria-invalid", String(!isValid));
    error.hidden = isValid;
  };

  const validators = {
    name(value) {
      return value.trim().length >= 2;
    },
    email(value) {
      return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim());
    },
    phone(value) {
      return !value.trim() || /^\+?[0-9\s()-]{7,}$/.test(value.trim());
    },
    subject(value) {
      return value.trim().length >= 2;
    },
    message(value) {
      return value.trim().length >= 10;
    }
  };

  const validateField = (fieldName) => {
    if (!form || !validators[fieldName]) {
      return true;
    }

    const input = form.elements[fieldName];
    const isValid = validators[fieldName](input.value);
    toggleFieldError(fieldName, isValid);
    return isValid;
  };

  const validateForm = () => {
    if (!form) {
      return true;
    }

    const fields = ["name", "email", "phone", "subject", "message"];
    let firstInvalidField = null;
    let isFormValid = true;

    fields.forEach((fieldName) => {
      const isFieldValid = validateField(fieldName);
      if (!isFieldValid && !firstInvalidField) {
        firstInvalidField = form.elements[fieldName];
      }
      isFormValid = isFormValid && isFieldValid;
    });

    if (!isFormValid) {
      firstInvalidField?.focus();
    }

    return isFormValid;
  };

  if (form && submitButton) {
    ["name", "email", "phone", "message"].forEach((fieldName) => {
      form.elements[fieldName]?.addEventListener("input", () => {
        validateField(fieldName);
      });
    });

    form.elements.subject?.addEventListener("change", () => {
      validateField("subject");
    });

    form.addEventListener("submit", async (event) => {
      event.preventDefault();

      if ((form.elements.website?.value || "").trim()) {
        setFormStatus("Thank you! Your message has been sent.", "success");
        form.reset();
        Object.keys(validators).forEach((fieldName) => toggleFieldError(fieldName, true));
        return;
      }

      if (!validateForm()) {
        setFormStatus("Please correct the errors highlighted above.", "error");
        return;
      }

      submitButton.disabled = true;
      submitButton.textContent = "Sending...";
      setFormStatus("Sending...", "success");

      try {
        const response = await fetch("/api/contact", {
          method: "POST",
          headers: {
            "Content-Type": "application/json"
          },
          body: JSON.stringify({
            name: form.elements.name.value.trim(),
            email: form.elements.email.value.trim(),
            phone: form.elements.phone.value.trim(),
            subject: form.elements.subject.value.trim(),
            message: form.elements.message.value.trim(),
            website: form.elements.website.value.trim()
          })
        });

        if (!response.ok) {
          let errorMessage = "Sorry, something went wrong. Please try again.";

          try {
            const data = await response.json();
            if (data?.error) {
              errorMessage = data.error;
            }
          } catch (_) {
            // Ignore JSON parsing errors and keep the fallback message.
          }

          throw new Error(errorMessage);
        }

        setFormStatus("Thank you! Your message has been sent.", "success");
        form.reset();
        Object.keys(validators).forEach((fieldName) => toggleFieldError(fieldName, true));
      } catch (error) {
        setFormStatus(error.message || "Network error. Please try again.", "error");
      } finally {
        submitButton.disabled = false;
        submitButton.textContent = "Send Message";
      }
    });
  }

  updateBackToTopButton();
  updateActiveNavLink();

  window.addEventListener("load", () => {
    body.classList.add("loaded");
  });
})();
